begin;
do $$
declare owner uuid:=gen_random_uuid(); other_user uuid:=gen_random_uuid(); photo uuid; post uuid; another uuid; first_comment uuid; reply_comment uuid; result jsonb; page jsonb; second_page jsonb; request_id uuid:=gen_random_uuid(); reply_request uuid:=gen_random_uuid(); i integer;
begin
 insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data) values(owner,owner::text||'@example.invalid','{"provider":"google","providers":["google"]}','{}'),(other_user,other_user::text||'@example.invalid','{"provider":"google","providers":["google"]}','{}');
 insert into public.humor_images(user_id,status,image_width,image_height) values(owner,'ready',600,800) returning id into photo;
 update public.humor_images set storage_path=owner::text||'/'||photo::text||'.png' where id=photo;
 insert into public.humor_captions(image_id,content) values(photo,'Comment transaction fixture') returning id into post;
 insert into public.humor_captions(image_id,content) values(photo,'Other comment fixture') returning id into another;
 result:=public.add_humor_comment(post,owner,'One',null,request_id); first_comment:=(result->'comment'->>'id')::uuid;
 if (result->>'commentCount')::integer<>1 then raise exception 'Wrong count'; end if;
 result:=public.add_humor_comment(post,owner,'One',null,request_id);
 if (result->>'commentCount')::integer<>1 or (result->'comment'->>'id')::uuid<>first_comment then raise exception 'Send retry duplicates comment'; end if;
 result:=public.add_humor_comment(post,owner,'Two',first_comment,reply_request); reply_comment:=(result->'comment'->>'id')::uuid;
 begin perform public.add_humor_comment(post,owner,'Two'||first_comment::text,null,reply_request);raise exception 'Ambiguous retry accepted';exception when others then if sqlerrm<>'Invalid request' then raise;end if;end;
 begin perform public.add_humor_comment(another,owner,'Cross-post',first_comment,gen_random_uuid()); raise exception 'Cross-post reply accepted'; exception when others then if sqlerrm<>'Reply no longer available' then raise;end if;end;
 perform public.add_humor_comment(post,owner,'Three',null,gen_random_uuid());
 begin perform public.add_humor_comment(post,owner,'Four',null,gen_random_uuid());raise exception 'Rate limit failed';exception when others then if sqlerrm<>'Comment rate limit' then raise;end if;end;
 begin perform public.add_humor_comment(post,other_user,repeat('🙂',281),null,gen_random_uuid());raise exception 'Length check failed';exception when others then if sqlerrm<>'Invalid comment' then raise;end if;end;
 request_id:=gen_random_uuid();result:=public.toggle_humor_comment_ha(first_comment,owner,request_id);
 if (result->>'haCount')::integer<>1 then raise exception 'Comment Ha failed';end if;
 result:=public.toggle_humor_comment_ha(first_comment,owner,request_id);if (result->>'haCount')::integer<>1 then raise exception 'Ha retry toggles';end if;
 begin perform public.delete_humor_comment(first_comment,other_user);raise exception 'Ownership check failed';exception when others then if sqlerrm<>'Only the author can delete this comment' then raise;end if;end;
 result:=public.delete_humor_comment(first_comment,owner);if (result->>'commentCount')::integer<>2 then raise exception 'Delete count failed';end if;
 if public.humor_comment_row(reply_comment,owner)->'replyTo'->>'authorName'<>'deleted' then raise exception 'Deleted reply target lost';end if;
 if (public.humor_post(post,owner)->>'commentCount')::integer<>2 then raise exception 'Detail count stale';end if;
 for i in 1..25 loop insert into public.humor_comments(caption_id,user_id,content) values(post,other_user,'Pagination '||i);end loop;
 page:=public.humor_comments_page(post,owner,'top',null,0,20);second_page:=public.humor_comments_page(post,owner,'top',(page->>'snapshotId')::uuid,20,20);
 if jsonb_array_length(page->'comments')<>20 or jsonb_array_length(second_page->'comments')<>7 then raise exception 'Wrong comment page size';end if;
 if exists(select 1 from jsonb_array_elements(page->'comments') a,jsonb_array_elements(second_page->'comments') b where a->>'id'=b->>'id') then raise exception 'Duplicate page comments';end if;
 perform public.toggle_humor_save(post,owner,gen_random_uuid());
 insert into public.humor_reports(user_id,caption_id,reason) values(other_user,post,'Other');
 insert into public.humor_comment_reports(user_id,comment_id,reason) values(other_user,reply_comment,'Other');
 perform public.toggle_humor_comment_ha(reply_comment,other_user,gen_random_uuid());
 update public.humor_captions set deleted_at=now() where id=post;
 if exists(select 1 from public.humor_comments where caption_id=post) or exists(select 1 from public.humor_comment_votes where comment_id=reply_comment) or exists(select 1 from public.humor_comment_reports where comment_id=reply_comment) or exists(select 1 from public.humor_saves where caption_id=post) or exists(select 1 from public.humor_reports where caption_id=post) then raise exception 'Post cleanup incomplete';end if;
 if public.humor_post(post,owner) is not null then raise exception 'Deleted post still readable';end if;
 if has_function_privilege('authenticated','public.add_humor_comment(uuid,uuid,text,uuid,uuid)','execute') or has_table_privilege('anon','public.humor_comment_votes','select') then raise exception 'Unsafe comment permissions';end if;
 if exists(select 1 from pg_class where relname in ('humor_comments','humor_comment_votes','humor_comment_reports','humor_comment_requests','humor_comment_ha_requests','humor_comment_rate_events','humor_comment_snapshots') and not relrowsecurity) then raise exception 'RLS missing';end if;
end $$;
rollback;
select 'PASS: counts, idempotency, 3/10s limit, Unicode limit, cross-post replies, ownership, @deleted, cursor pagination, cascading cleanup, private RPCs and RLS. All fixtures rolled back.' as result;
